async def settle_scroll(p):
 stable=0;previous=None;started=time.monotonic()
 for i in range(45):
  current=await p.evaluate('scrollY')
  stable=stable+1 if previous is not None and abs(current-previous)<.2 else 0
  if stable>=5 and time.monotonic()-started>=1:return
  previous=current;await p.wait_for_timeout(60)
 raise AssertionError('Native scrolling did not settle')
